<style lang="scss" scoped src="./table-header-cell.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { MountingPortal } from "portal-vue";
import { has } from "../../util/has";
import Icon from "../icon/icon.vue";
import { IconShape } from "../icon/icon.constants";
import TableHeaderFilter from "../table-header-filter/table-header-filter.vue";
import { TableCellSize, TableCellSizeValues } from "../table/table.constants";
import {
  TableSortMode,
  TableHeaderCellAlignment,
  TableHeaderCellAlignmentValues,
  TableHeaderMode
} from "./table-header-cell.constants";

@Component({
  components: {
    Icon,
    MountingPortal,
    TableHeaderFilter
  }
})
export default class TabelHeaderCell extends Vue {
  @Prop({
    type: String,
    default: TableHeaderCellAlignment.LEFT,
    validator: has(TableHeaderCellAlignmentValues)
  })
  align;

  @Prop({
    type: String,
    default: TableCellSize.SMALL,
    validator: has(TableCellSizeValues)
  })
  size;

  @Prop({
    type: String,
    default: ""
  })
  name;

  @Prop({
    type: Boolean,
    default: false
  })
  enableFilter;

  // For empty table
  @Prop({
    type: Boolean,
    default: false
  })
  disable;

  @Prop({
    type: Array,
    default: () => []
  })
  filterOptions;

  @Prop({
    type: Array,
    default: () => []
  })
  sortOptions;

  @Prop({
    type: String,
    default: ""
  })
  searchDefaultValue;

  @Prop({
    type: Boolean,
    default: true
  })
  hasBorder;

  @Prop({
    type: String,
    default: TableHeaderMode.DEFAULT
  })
  mode;

  @Prop({
    type: Boolean,
    default: true
  })
  allIsSelected;

  headerBox = null;
  wasOpen = false;
  hovered = false;

  TableHeaderCellAlignment = TableHeaderCellAlignment;
  TableSortMode = TableSortMode;
  IconShape = IconShape;

  filterOptionSelected = [];
  searchValue = "";
  selectAll = true;

  beforeMount() {
    this.selectAll = true;
    for (let i = 0; i < this.filterOptions.length; i++) {
      this.filterOptionSelected[i] = this.filterOptions[i].selected;
      if (!this.filterOptionSelected[i]) this.selectAll = false;
    }
  }

  beforeUpdate() {
    this.selectAll = this.allIsSelected;
    this.searchValue = this.searchDefaultValue;
  }

  get borderClass() {
    return this.hasBorder
      ? "TableHeaderCell--has_border"
      : "TableHeaderCell--no_border";
  }

  get alignClass() {
    if (!this.enableFilter) {
      return this.align;
    } else {
      if (this.align === TableHeaderCellAlignment.CENTER) {
        return this.align;
      } else {
        return "TableHeaderCell--between";
      }
    }
  }

  get modeClass() {
    return this.mode;
  }

  get sizeClass() {
    if (this.disableFilter) return `${this.size}Empty`;
    return this.size;
  }

  get opened() {
    return Boolean(this.headerBox) && this.enableFilter;
  }

  get filtered() {
    // this.searchValue !== "" ||
    return !this.selectAll;
  }

  get label() {
    if (!this.allIsSelected || this.searchDefaultValue !== "")
      return `${this.name} (Filtered)`;

    return this.name;
  }

  get iconColor() {
    if (this.opened) return "#ffffff";

    if (!this.allIsSelected || this.searchDefaultValue !== "") return "#2356f6";

    return "#65667780";
  }

  handleClickHeaderCell() {
    if (!this.enableFilter || !this.$refs.container) return;

    if (this.headerBox || this.wasOpen) {
      this.headerBox = void 0;
      /**
       * filterClose event when user closes the filter board
       *
       * @event filterClose
       */
      this.$emit("filterClose");
    } else {
      const box = this.$refs.container.getBoundingClientRect();
      this.headerBox = {
        left: box.x,
        top: box.y,
        width: box.width,
        height: box.height,
        right: box.right,
        bottom: box.bottom
      };
      /**
       * filterClose event when user opens the filter board
       *
       * @event filterOpen
       */
      this.$emit("filterOpen");
    }
  }

  handleMouseDown() {
    this.wasOpen = Boolean(this.headerBox);
  }

  handleClose() {
    if (this.headerBox) {
      this.headerBox = void 0;
      /**
       * filterClose event when user closes the filter board
       *
       * @event filterClose
       */
      this.$emit("filterClose");
    }
  }

  handleOver() {
    this.hovered = true;
  }

  handleOut() {
    this.hovered = false;
  }

  handleSortIncrease() {
    /**
     * onSortIncrease when user selects sort increase
     *
     * @event onSortIncrease
     */
    this.$emit("onSortIncrease");
  }

  handleSortDecrease() {
    /**
     * onSortDecrease when user selects sort decrease
     *
     * @event
     */
    this.$emit("onSortDecrease");
  }

  handleSort(index) {
    const option = this.sortOptions[index];
    /**
     * Sort event when a sort option is selected
     *
     * @event sort
     */
    this.$emit("sort", { mode: option.mode, compare: option.compare });
  }

  handleInput(value) {
    this.searchValue = value;
    /**
     * input event when user input something into the search field
     *
     * @event input
     */
    this.$emit("input", value);
  }

  handleSelectOption(index) {
    this.filterOptionSelected[index] = !this.filterOptionSelected[index];
    this.selectAll =
      this.filterOptionSelected.find(option => option === false) === void 0;
    /**
     * selectOption event when a filter option is selected
     *
     * @event selectOption
     */
    this.$emit("selectOption", index);
  }

  handleSelectAll() {
    this.selectAll = true;
    /**
     * SelectAll event when user clicks 'select all'
     *
     * @event selectAll
     */
    this.$emit("selectAll");
  }

  handleClear() {
    this.selectAll = false;
    /**
     * Clear event when user click 'clear'
     *
     * @event clear
     */
    this.$emit("clear");
  }
}
</script>

<template>
  <div
    :class="[
      'TableHeaderCell',
      sizeClass,
      borderClass,
      this.disable ? 'TableHeaderCell__Disable' : '',
      opened ? 'TableHeaderCell__Open' : '',
      modeClass
    ]"
    @click="handleClickHeaderCell"
    @mouseover="handleOver"
    @mouseout="handleOut"
    @mousedown="handleMouseDown"
    ref="container"
  >
    <div v-if="!enableFilter" :class="['TableHeaderCell__Content', alignClass]">
      <div class="TableHeaderCell__Name">{{ label }}</div>
    </div>
    <div v-else class="TableHeaderCell__Sort">
      <div
        v-if="align === TableHeaderCellAlignment.RIGHT"
        :class="['TableHeaderCell__Content', alignClass]"
      >
        <div class="TableHeaderCell__Arrow">
          <Icon :shape="IconShape.FILTER_LIST" :size="20" :color="iconColor" />
        </div>
        <div class="TableHeaderCell__Name">{{ label }}</div>
      </div>
      <div v-else :class="['TableHeaderCell__Content', alignClass]">
        <div class="TableHeaderCell__Name">{{ label }}</div>
        <div
          :class="[
            'TableHeaderCell__Arrow',
            align === TableHeaderCellAlignment.CENTER
              ? 'TableHeaderCell--padding'
              : ''
          ]"
        >
          <Icon :shape="IconShape.FILTER_LIST" :size="20" :color="iconColor" />
        </div>
      </div>
    </div>
    <TableHeaderFilter
      v-if="opened"
      :bounds="headerBox"
      :coverBounds="false"
      :dropdownWidth="207"
      :filterOptions="filterOptions"
      :sortOptions="sortOptions"
      :searchDefaultValue="searchDefaultValue"
      @selectAll="handleSelectAll"
      @clear="handleClear"
      @selectOption="handleSelectOption"
      @close="handleClose"
      @input="handleInput"
      @sort="handleSort"
      @onSortIncrease="handleSortIncrease"
      @onSortDecrease="handleSortDecrease"
    />
  </div>
</template>
